-- Append to the isolated applications fixture transaction; never run on operation.
select public.save_sowing_group(pg_temp.group_data(),pg_temp.stages());
select public.create_application_order(pg_temp.order_data()||'{"source_group_id":"91000000-0000-4000-8000-000000000001"}',pg_temp.stages(),pg_temp.mixture());
create function pg_temp.menus(keys text[]) returns void language sql as $$
  select public.set_user_menu_access('10000000-0000-4000-8000-000000000002','viewer',true,
    array['20000000-0000-4000-8000-000000000001']::uuid[],keys,(select access_version from public.profiles where id='10000000-0000-4000-8000-000000000002'))
$$;
select pg_temp.expect_error($q$select public.set_user_menu_access('10000000-0000-4000-8000-000000000001','viewer',true,'{}','{}',0)$q$,'administrador activo','último administrador no se degrada');
select pg_temp.expect_error($q$select pg_temp.menus(array['users'])$q$,'requieren administrador','menú no eleva rol de lector');
select pg_temp.expect_error($q$select pg_temp.menus(array['inventado'])$q$,'menú inválido','clave de menú desconocida rechazada');
select pg_temp.assert_true((select access_version=0 from public.profiles where id='10000000-0000-4000-8000-000000000002'),'rechazos no cambian versión');
select pg_temp.expect_error($q$select public.set_user_menu_access('10000000-0000-4000-8000-000000000002','viewer',true,array['ffffffff-ffff-4fff-8fff-ffffffffffff']::uuid[],array['queries'],0)$q$,'agrícolas válidas','agrícola inexistente no cambia acceso');
select pg_temp.menus('{}');
select pg_temp.assert_true((select count(*)=1 from public.user_access_changes),'cambio genera historial atómico');
select pg_temp.assert_true((select after->'menus'='[]'::jsonb and changed_by_name<>'' from public.user_access_changes),'historial conserva menús y autor');
select pg_temp.expect_error($q$select public.set_user_menu_access('10000000-0000-4000-8000-000000000002','viewer',true,'{}',array['queries'],0)$q$,'acceso cambió','conflicto no sobreescribe permisos');
select pg_temp.assert_true((select count(*)=1 from public.user_access_changes),'conflicto no duplica historial');
select pg_temp.expect_error($q$update public.profiles set menu_permissions=array['queries']$q$,'permission denied','administrador usa RPC para permisos');
select pg_temp.expect_error($q$delete from public.user_access_changes$q$,'permission denied','historial no se elimina por cliente');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select count(*)=0 from public.application_orders),'sin menús no consulta órdenes');
select pg_temp.assert_true((select count(*)=0 from public.sowing_projects),'sin menús no consulta proyectos');
select pg_temp.assert_true((select count(*)=0 from public.sowing_groups),'sin menús no consulta grupos');
select pg_temp.assert_true((select count(*)=0 from public.products),'sin menú no consulta catálogo por REST/SQL');
select pg_temp.assert_true(public.menu_reference_catalogs()='{}'::jsonb,'sin secciones no recibe referencias');
select pg_temp.assert_true((select count(*)=0 from public.user_access_changes),'lector no ve historial de permisos');
select pg_temp.expect_error($q$select public.application_query('{"operation":"historial"}')$q$,'no tiene acceso','consulta directa requiere menú');
select pg_temp.expect_error($q$select public.application_query_resolve('{"operation":"uso_producto"}',null)$q$,'no tiene acceso','resolver requiere menú');
select pg_temp.expect_error($q$select public.application_query_stamp()$q$,'no tiene acceso','sello no revela revisión sin menú');
select pg_temp.expect_error($q$select pg_temp.menus(array['queries'])$q$,'administrador','lector no cambia su acceso');
select pg_temp.expect_error($q$update public.profiles set role='admin' where id=auth.uid()$q$,'permission denied','lector no escala por tabla');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
select pg_temp.menus(array['queries']);
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select count(*)=1 from public.application_orders),'consultas obtiene datos de sus agrícolas');
select pg_temp.assert_true((select count(*)=0 from public.sowing_projects where agricultural_unit_id='20000000-0000-4000-8000-000000000002'),'menú no amplía agrícolas');
select pg_temp.assert_true((select count(*)=0 from public.products),'consultas no habilita catálogo completo');
select pg_temp.assert_true(jsonb_array_length(public.menu_reference_catalogs()->'products')=2,'referencias solo incluyen productos usados');
select pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.menu_reference_catalogs()->'products') p where p ? 'default_dose'),'referencias no incluyen columnas de mantenimiento');
select pg_temp.assert_true(jsonb_array_length(public.menu_reference_catalogs()->'agricultural_units')=1,'referencias conservan agrícola asignada');
select pg_temp.assert_true((public.application_query('{"operation":"historial"}')#>>'{summary,destination_count}')::int=2,'RPC de consulta funciona con catálogo oculto');
select pg_temp.assert_true(public.application_query_resolve('{"operation":"uso_producto","product":"Producto original"}',null)->>'revision' is not null,'resolver puede identificar producto sin abrir catálogo');
select pg_temp.assert_true((select count(*)=0 from public.products),'contexto de consulta no filtra privilegios a lectura siguiente');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
select pg_temp.menus(array['catalog:crops']);
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select count(*)=1 from public.crops),'permiso de catálogo concreto permite su lectura');
select pg_temp.assert_true((select count(*)=0 from public.varieties),'permiso no se extiende a otro catálogo');
select pg_temp.assert_true((select count(*)=0 from public.application_targets),'catálogo no abre datos operativos');
select pg_temp.expect_error($q$select public.application_query_stamp()$q$,'no tiene acceso','revocación corta RPC con la misma sesión');
reset role;
insert into auth.users(id,email,raw_user_meta_data) values('10000000-0000-4000-8000-000000000099','menus-new@example.invalid','{"menu_permissions":["queries"],"role":"admin"}');
select pg_temp.assert_true((select menu_permissions='{}' and role='viewer' from public.profiles where id='10000000-0000-4000-8000-000000000099'),'cuenta nueva no hereda claims editables ni menús');
update public.profiles set active=false where id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select count(*)=0 from public.crops),'perfil inactivo no conserva menús con JWT anterior');
select pg_temp.expect_error($q$select public.menu_reference_catalogs()$q$,'cuenta activa','perfil inactivo no obtiene referencias');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
select pg_temp.assert_true(rcfito_private.has_menu('users') and rcfito_private.has_menu('connection') and rcfito_private.has_menu('ai_capture'),'administrador conserva secciones protegidas');
reset role;
set local role anon;
select pg_temp.expect_error($q$select public.menu_reference_catalogs()$q$,'permission denied','anónimo sin referencias');
select pg_temp.expect_error($q$select public.set_user_menu_access(null,'admin',true,'{}','{}',0)$q$,'permission denied','anónimo no asigna menús');
reset role;
rollback;
